API_BAKED.forEach(t=>{ if(!TITLES.some(x=>x.title.toLowerCase()===t.title.toLowerCase())){ TITLES.push(t); } });
const bySlug = {}; TITLES.forEach(t => bySlug[t.slug] = t);
const NF = TITLES.filter(t => t.nfRank).sort((a,b) => a.nfRank - b.nfRank);
const MOVIES = TITLES.filter(t => t.type === 'movie');
const SERIES = TITLES.filter(t => t.type === 'series' && !t.nfRank);
const ALL_GENRES = [...new Set(TITLES.flatMap(t => t.genres))].sort();

/* ================= STATE (localStorage, this browser only) ================= */
const store = {
  get(k, d){ try { const v = localStorage.getItem('cs_' + k); return v ? JSON.parse(v) : d; } catch(e){ return d; } },
  set(k, v){ try { localStorage.setItem('cs_' + k, JSON.stringify(v)); } catch(e){} }
};

/* ================= ANALYTICS (single hook — powers the Dashboard view) =================
   window.ReelOpalAnalytics records, in this browser only (localStorage):
   page views per view and per day, a per-day unique-visitor flag, top
   titles/pages (all time + today), referrer type (document.referrer +
   utm_source / utm_medium / utm_campaign), smartlink clicks and full-details clicks (all time + today). The Dashboard view (#/dashboard) renders
   ReelOpalAnalytics.summary() — there is no second counter system.
   Inspect manually with ReelOpalAnalytics.summary() in the console.
   GA4/Plausible connect via GA_MEASUREMENT_ID / PLAUSIBLE_DOMAIN above
   (empty = off, nothing is sent anywhere). */
const ReelOpalAnalytics = {
  data: store.get('analytics', {days:{}, pages:{}, titles:{}, referrers:{}, smartlink:0, details:0, utm:{}}),
  today(){ return new Date().toISOString().slice(0, 10); },
  save(){ store.set('analytics', this.data); },
  ensure(){ const d = this.data; d.days = d.days || {}; d.pages = d.pages || {}; d.titles = d.titles || {}; d.referrers = d.referrers || {}; d.utm = d.utm || {}; d.smartlink = d.smartlink || 0; d.details = d.details || 0; return d; },
  day(dateStr){ const d = this.ensure(); const key = dateStr || this.today(); const day = d.days[key] = d.days[key] || {views:0, unique:false, titles:{}, pages:{}, referrers:{}, smartlink:0, details:0, utm:{}}; day.titles = day.titles || {}; day.pages = day.pages || {}; day.referrers = day.referrers || {}; day.utm = day.utm || {}; day.smartlink = day.smartlink || 0; day.details = day.details || 0; day.views = day.views || 0; return day; },
  utmParams(){ const out = {}; try { const fromSearch = new URLSearchParams(location.search || ''); const fromHash = new URLSearchParams((location.hash.split('?')[1] || '')); ['utm_source','utm_medium','utm_campaign'].forEach(k => { const v = fromSearch.get(k) || fromHash.get(k); if (v) out[k] = String(v).slice(0, 80); }); } catch(e){} return out; },
  refType(){ const u = this.utmParams(); const src = (u.utm_source || '').toLowerCase(); const med = (u.utm_medium || '').toLowerCase(); if (src || med) { if (/google|bing|duckduckgo|yahoo|ecosia/.test(src) || /cpc|ppc|organic|search/.test(med)) return 'search'; if (/tiktok|instagram|facebook|twitter|x\.com|youtube|pinterest|reddit/.test(src) || med === 'social') return 'social'; return 'other'; } const r = document.referrer || ''; if (!r) return 'direct'; if (/google|bing|duckduckgo|yahoo|ecosia/.test(r)) return 'search'; if (/tiktok|instagram|facebook|twitter|x\.com|youtube|pinterest|reddit/.test(r)) return 'social'; return 'other'; },
  pageview(view){ this.ensure(); const day = this.day(); day.views++; if (!store.get('visitor_' + this.today(), false)) { store.set('visitor_' + this.today(), true); day.unique = true; } this.data.pages[view] = (this.data.pages[view] || 0) + 1; day.pages[view] = (day.pages[view] || 0) + 1; const rt = this.refType(); this.data.referrers[rt] = (this.data.referrers[rt] || 0) + 1; day.referrers[rt] = (day.referrers[rt] || 0) + 1; const u = this.utmParams(); Object.keys(u).forEach(k => { const key = k + '=' + u[k]; this.data.utm[key] = (this.data.utm[key] || 0) + 1; day.utm[key] = (day.utm[key] || 0) + 1; }); this.save(); },
  title(slug){ this.ensure(); this.data.titles[slug] = (this.data.titles[slug] || 0) + 1; const day = this.day(); day.titles[slug] = (day.titles[slug] || 0) + 1; this.save(); },
  smartlinkClick(src){ this.ensure(); this.data.smartlink++; this.day().smartlink++; this.save(); },
  detailsClick(key){ this.ensure(); this.data.details++; this.day().details++; this.save(); },
  summary(){ this.ensure(); return JSON.parse(JSON.stringify(this.data)); }
};
window.ReelOpalAnalytics = ReelOpalAnalytics;
let watchlist = new Set(store.get('watchlist', []));
function saveWl(){ store.set('watchlist', [...watchlist]); renderWlBadge(); }
function renderWlBadge(){ const b = document.getElementById('wlCount'); b.hidden = !watchlist.size; b.textContent = watchlist.size; }

/* ================= HELPERS ================= */
const $ = s => document.querySelector(s);
const esc = s => String(s == null ? '' : s).replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
/* Real-paths build: pages live at /, /movies/, /titles/<slug>/ ... so a bare
   "assets/..." poster path only resolves from /. asset() prefixes the right
   number of ../ for the CURRENT page depth (recomputed per call, so SPA
   navigation across depths stays correct). */
function asset(p){ var d = location.pathname.replace(/\/$/,'').split('/').filter(Boolean).length; var pre=''; for (var i=0;i<d;i++) pre+='../'; return pre + p; }
let toastTimer;
function toast(msg){ const t = $('#toast'); t.textContent = msg; t.classList.add('on'); clearTimeout(toastTimer); toastTimer = setTimeout(() => t.classList.remove('on'), 2600); }
function scoreBadge(t){
  if (t.nfRank) return '<span class="bdg red">Netflix #' + t.nfRank + '</span>';
  if (t.type === 'series' && t.rating) return '<span class="bdg">★ ' + t.rating.toFixed(1) + '</span>';
  if (t.type === 'movie') return '<span class="bdg blue">' + (t.region === 'EU' ? 'UK' : 'US') + ' chart #' + t.chart + '</span>';
  return '';
}
const GENRE_COLORS={'Drama':'#ff4d2e','Comedy':'#ffb703','Crime':'#38bdf8','Horror':'#ff2e88','Thriller':'#a6e22e','Action':'#ff6b35','Science-Fiction':'#00d9b5','Fantasy':'#c084fc','Romance':'#fb7185','Adventure':'#facc15','Animation':'#34d399','Family':'#60a5fa','Mystery':'#f472b6','War':'#94a3b8','Western':'#d97706','Documentary':'#2dd4bf'};
function genreColor(g){return GENRE_COLORS[g]||'#ffb703'}
function cardHTML(t, ranked){
  const inWl = watchlist.has(t.slug);
  const meta = [t.year, t.type === 'movie' ? 'Movie' : (t.network === 'Netflix' ? 'Netflix series' : 'Series')].filter(Boolean).join(' · ');
  const gc = genreColor(t.genres[0]||'');
  const inner =
    '<div class="ph"><img loading="lazy" width="352" height="528" src="' + esc(asset(t.poster)) + '" alt="Poster for ' + esc(t.title) + ' (' + esc(t.year) + ')" />' +
    scoreBadge(t) +
    '<button class="wl-btn' + (inWl ? ' in' : '') + '" data-wl="' + t.slug + '" aria-label="' + (inWl ? 'Remove from' : 'Add to') + ' watchlist" title="Watchlist">' + (inWl ? '✓' : '＋') + '</button></div>' +
    '<h3>' + esc(t.title) + '</h3><div class="cm">' + esc(meta) + (t.type === 'series' && t.rating ? ' · ★ ' + t.rating.toFixed(1) : '') + '</div>' +
    (t.genres[0] ? '<span class="gtag" style="background:'+gc+';color:#111">' + esc(t.genres[0]) + '</span>' : '') +
    (t.overview ? '<div class="ov">' + esc(t.overview.replace(/<[^>]+>/g,'').slice(0,110)) + '</div>' : '');
  if (ranked) return '<div class="rank-wrap"><span class="rank-num">' + t.nfRank + '</span><article class="card" data-open="' + t.slug + '" tabindex="0" role="link" aria-label="' + esc(t.title) + '">' + inner + '</article></div>';
  return '<article class="card" data-open="' + t.slug + '" tabindex="0" role="link" aria-label="' + esc(t.title) + '">' + inner + '</article>';
}
function fillTrack(id, list, ranked){ const el = document.getElementById(id); if (el) el.innerHTML = list.map(t => cardHTML(t, ranked)).join(''); }
function fillGrid(id, list, ranked){ fillTrack(id, list, ranked); }
function sortList(list, mode){
  const a = [...list];
  if (mode === 'rating') a.sort((x,y) => (y.rating || 0) - (x.rating || 0) || (y.nfRank ? 0 : 0));
  else if (mode === 'new') a.sort((x,y) => String(y.year).localeCompare(String(x.year)));
  else if (mode === 'az') a.sort((x,y) => x.title.localeCompare(y.title));
  else if (mode === 'chart') a.sort((x,y) => (x.chart || 99) - (y.chart || 99));
  return a;
}

/* ================= HOME ================= */
const HERO = [MOVIES[0] ? MOVIES[0].slug : '', MOVIES[1] ? MOVIES[1].slug : '', MOVIES[2] ? MOVIES[2].slug : ''].map(s => bySlug[s]).filter(Boolean);
let heroIdx = 0, heroTimer = null;
function renderHero(){
  const t = HERO[heroIdx]; if (!t) return;
  $('#heroBg').style.backgroundImage = 'url("' + asset(t.poster) + '")';
  const hp = $('#heroPoster'); hp.src = asset(t.poster); hp.alt = 'Poster for ' + t.title + ' (' + t.year + ')';
  $('#heroKick').textContent = t.nfRank ? 'Netflix Trending #' + t.nfRank : (t.type === 'movie' ? (t.region === 'EU' ? 'UK chart #' + t.chart : 'US chart #' + t.chart) + ' this week' : 'Top rated series · ★ ' + (t.rating ? t.rating.toFixed(1) : ''));
  $('#heroTitle').textContent = t.title;
  $('#heroMeta').innerHTML =
    (t.rating ? '<span class="star">★ ' + t.rating.toFixed(1) + '</span>' : '') +
    '<span>' + esc(t.year) + '</span><span>' + esc(t.genres.join(' · ')) + '</span>' +
    (t.network ? '<span>' + esc(t.network) + '</span>' : '') + (t.seasons ? '<span>' + t.seasons + ' season' + (t.seasons > 1 ? 's' : '') + ' · ' + t.episodes + ' episodes</span>' : '');
  $('#heroOv').textContent = t.overview;
  $('#heroCta').innerHTML =
    '<a class="btn red" href="/titles/' + t.slug + '/">▶ View details</a>' +
    (t.trailer ? '<button class="btn" data-trailer="' + t.slug + '">🎬 Trailer</button>' : '') +
    '<button class="btn smart" data-smartlink="hero">⚡ Sponsored pick</button>' +
    '<button class="btn ghost" data-wl="' + t.slug + '">' + (watchlist.has(t.slug) ? '✓ In watchlist' : '＋ Watchlist') + '</button>';
  $('#heroDots').innerHTML = HERO.map((h, i) => '<button data-hero="' + i + '" class="' + (i === heroIdx ? 'on' : '') + '" aria-label="Featured: ' + esc(h.title) + '"></button>').join('');
}
function heroGo(i){ heroIdx = (i + HERO.length) % HERO.length; renderHero(); }
function startHero(){ clearInterval(heroTimer); heroTimer = setInterval(() => heroGo(heroIdx + 1), 7000); }

const MOODS = {
  thrill: ['Thriller','Action','Horror','Crime'], mind: ['Science-Fiction','Mystery','Fantasy'],
  laugh: ['Comedy'], epic: ['War','Adventure','Drama','Action'], feel: ['Family','Romance','Animation','Drama'], dark: ['Crime','Horror','Thriller','Drama']
};
let lastPick = null;
function moodPick(mood, btn){
  document.querySelectorAll('#moodRow button').forEach(b => b.classList.toggle('on', b === btn));
  const pool = TITLES.filter(t => t.genres.some(g => MOODS[mood].includes(g)));
  let pick = pool[Math.floor(Math.random() * pool.length)];
  if (pick && lastPick && pick.slug === lastPick.slug && pool.length > 1) pick = pool[(pool.indexOf(pick) + 1) % pool.length];
  lastPick = pick; if (!pick) return;
  const box = $('#pickBox');
  box.innerHTML = '<img loading="lazy" width="184" height="276" src="' + esc(asset(pick.poster)) + '" alt="Poster for ' + esc(pick.title) + ' (' + esc(pick.year) + ')" /><div>' +
    '<span class="kick">Your pick</span><h3 style="margin:4px 0 4px;font-size:22px">' + esc(pick.title) + (pick.rating ? ' <span style="color:var(--gold);font-size:16px">★ ' + pick.rating.toFixed(1) + '</span>' : '') + '</h3>' +
    '<p style="margin:0 0 12px;color:var(--muted)">' + esc(pick.overview.slice(0, 190)) + '…</p>' +
    '<div style="display:flex;gap:9px;flex-wrap:wrap"><a class="btn red sm" href="/titles/' + pick.slug + '/">View details</a>' +
    '<button class="btn sm" data-mood-again="' + mood + '">↻ Another one</button></div></div>';
  box.classList.add('on');
}

/* ================= BROWSE PAGES ================= */
function genreOptions(sel, list){
  const el = document.getElementById(sel); if (!el || el.options.length > 1) return;
  const gs = [...new Set(list.flatMap(t => t.genres))].sort();
  gs.forEach(g => { const o = document.createElement('option'); o.value = g; o.textContent = g; el.appendChild(o); });
}
function renderMovies(){
  genreOptions('mvGenre', MOVIES);
  const region = $('#mvRegion').value, genre = $('#mvGenre').value, sort = $('#mvSort').value;
  let list = MOVIES.filter(m => (!region || m.region === region) && (!genre || m.genres.includes(genre)));
  list = sortList(list, sort);
  fillGrid('mvGrid', list);
  $('#mvCount').textContent = list.length + ' movies';
}
function renderSeries(){
  genreOptions('srGenre', SERIES.concat(NF));
  const genre = $('#srGenre').value, min = parseFloat($('#srRating').value), sort = $('#srSort').value;
  let list = SERIES.concat(NF).filter(s => (!genre || s.genres.includes(genre)) && (!min || (s.rating || 0) >= min));
  list = sortList(list, sort);
  fillGrid('srGrid', list);
  $('#srCount').textContent = list.length + ' series';
}
let genreState = '';
function renderGenres(){
  const chips = $('#genreChips');
  chips.innerHTML = '<button class="chip' + (!genreState ? ' on' : '') + '" data-genre="">All</button>' +
    ALL_GENRES.map(g => '<button class="chip' + (genreState === g ? ' on' : '') + '" data-genre="' + esc(g) + '">' + esc(g) + ' (' + TITLES.filter(t => t.genres.includes(g)).length + ')</button>').join('');
  const type = $('#gnType').value, sort = $('#gnSort').value;
  let list = TITLES.filter(t => (!genreState || t.genres.includes(genreState)) && (!type || t.type === type));
  list = sortList(list, sort);
  fillGrid('gnGrid', list);
  $('#gnCount').textContent = list.length + ' titles';
}
function renderSearch(q){
  const query = (q || '').trim().toLowerCase();
  const list = !query ? TITLES : TITLES.filter(t =>
    t.title.toLowerCase().includes(query) || t.genres.some(g => g.toLowerCase().includes(query)) ||
    (t.network || '').toLowerCase().includes(query) || (t.director || '').toLowerCase().includes(query) ||
    (t.cast || []).some(c => c.name.toLowerCase().includes(query) || c.character.toLowerCase().includes(query)));
  fillGrid('qGrid', sortList(list, 'rating'));
  $('#qCount').textContent = list.length + ' result' + (list.length === 1 ? '' : 's') + (query ? ' for “' + q + '”' : '');
}
function renderWatchlist(){
  const list = TITLES.filter(t => watchlist.has(t.slug));
  fillGrid('wlGrid', list);
  $('#wlEmpty').style.display = list.length ? 'none' : 'block';
  $('#exportBtn').textContent = '⬇ Export watchlist';
}

/* ================= DETAIL ================= */
let currentDetail = null;
function renderDetail(slug){
  const t = bySlug[slug]; if (!t) { nav('/'); return; }
  currentDetail = t;
  document.title = t.title + ' (' + t.year + ') — ' + (t.type === 'movie' ? 'Movie' : 'Series') + ' | ReelOpal';
  $('#dPoster').src = asset(t.poster); $('#dPoster').alt = 'Poster for ' + t.title + ' (' + t.year + ')';
  $('#dKick').textContent = t.nfRank ? 'Netflix Trending #' + t.nfRank : (t.type === 'movie' ? (t.region === 'EU' ? 'UK / Europe chart #' + t.chart : 'US chart #' + t.chart) : 'Top rated series');
  $('#dTitle').textContent = t.title;
  const meta = [];
  if (t.rating) meta.push('<span class="g">★ ' + t.rating.toFixed(1) + ' audience rating</span>');
  meta.push('<span>' + esc(t.year) + '</span>');
  t.genres.forEach(g => meta.push('<span>' + esc(g) + '</span>'));
  if (t.network) meta.push('<span>' + esc(t.network) + '</span>');
  if (t.runtime) meta.push('<span>≈ ' + t.runtime + ' min / episode</span>');
  if (t.director) meta.push('<span>Director: ' + esc(t.director) + '</span>');
  if (t.price) meta.push('<span>From ' + esc(t.price) + ' on Apple TV</span>');
  $('#dMeta').innerHTML = meta.join('');
  $('#dOv').textContent = t.overview;
  const watch = $('#dWatch'); watch.href = t.source;
  watch.textContent = t.type === 'movie' ? '▶ Watch on Apple TV (official)' : (t.network === 'Netflix' ? '▶ View on TVMaze — official links' : '▶ View official provider page');
  const tr = $('#dTrailer'); tr.hidden = !t.trailer; tr.dataset.trailer = t.slug;
  const wl = $('#dWl'); wl.innerHTML = watchlist.has(t.slug) ? '✓ In your watchlist (tap to remove)' : '＋ Add to watchlist';
  const castWrap = $('#dCastWrap');
  if (t.cast && t.cast.length) { castWrap.style.display = 'block'; $('#dCast').innerHTML = t.cast.map(c => '<span>' + esc(c.name) + ' <i>as ' + esc(c.character) + '</i></span>').join(''); }
  else castWrap.style.display = 'none';
  /* full breakdown (open) */
  const facts = [];
  if (t.type === 'series') {
    facts.push('<p><strong>Seasons:</strong> ' + (t.seasons || '—') + ' &nbsp;·&nbsp; <strong>Total episodes:</strong> ' + (t.episodes || '—') + ' &nbsp;·&nbsp; <strong>Status:</strong> ' + esc(t.status || '—') + '</p>');
    facts.push('<p><strong>Episode guide:</strong> every season of ' + esc(t.title) + ' is indexed on its official TVMaze page — runtimes average ' + (t.runtime || '—') + ' minutes per episode, so a full rewatch runs about ' + (t.episodes && t.runtime ? Math.round(t.episodes * t.runtime / 60) + ' hours' : '—') + '.</p>');
  } else {
    facts.push('<p><strong>Chart performance:</strong> #' + t.chart + ' on the ' + (t.region === 'EU' ? 'UK (Europe)' : 'US') + ' Apple TV movie chart, snapshot Nov 16, 2026. <strong>Director:</strong> ' + esc(t.director || '—') + '. <strong>Store price:</strong> ' + esc(t.price || 'see store') + '.</p>');
  }
  if (t.cast && t.cast.length) facts.push('<p><strong>Full top-billed cast:</strong> ' + t.cast.map(c => esc(c.name) + ' (' + esc(c.character) + ')').join(', ') + '.</p>');
  facts.push('<p><strong>HD poster pack:</strong> the official one-sheet for ' + esc(t.title) + ' in print resolution. <a href="' + esc(asset(t.poster)) + '" download>Download the HD poster</a></p>');
  facts.push('<p><strong>Where to watch legally:</strong> open the official provider page with the red button — availability differs between the US and Europe, and the provider page always shows the options for your region.</p>');
  $('#detailContent').innerHTML = facts.join('');
  $('#detailBox').classList.add('open');
  $('#dDetails').textContent = '📋 Full details & HD pack';
  $('#dDetails').onclick = () => document.getElementById('detailBox').scrollIntoView({behavior:'smooth'});
  const rel = TITLES.filter(x => x.slug !== t.slug && x.genres.some(g => t.genres.includes(g))).sort((a,b) => (b.rating || 0) - (a.rating || 0)).slice(0, 10);
  fillTrack('relTrack', rel);
  /* dynamic structured data: Movie/TVSeries + VideoObject + BreadcrumbList */
  let ld = document.getElementById('dynLd'); if (ld) ld.remove();
  ld = document.createElement('script'); ld.type = 'application/ld+json'; ld.id = 'dynLd';
  const canon = BASE_CANONICAL + '/titles/' + t.slug + '/';
  const entity = {'@type': t.type === 'movie' ? 'Movie' : 'TVSeries', '@id': canon, name: t.title, url: canon, datePublished: t.year, genre: t.genres, description: t.overview, image: BASE_CANONICAL + '/' + t.poster};
  if (t.rating) entity.aggregateRating = {'@type': 'AggregateRating', ratingValue: t.rating, bestRating: 10};
  if (t.cast && t.cast.length) entity.actor = t.cast.map(c => ({'@type': 'Person', name: c.name}));
  if (t.seasons) entity.numberOfSeasons = t.seasons;
  if (t.episodes) entity.numberOfEpisodes = t.episodes;
  const graph = [entity, {'@type': 'BreadcrumbList', 'itemListElement': [{'@type': 'ListItem', 'position': 1, 'name': 'Home', 'item': BASE_CANONICAL}, {'@type': 'ListItem', 'position': 2, 'name': t.type === 'movie' ? 'Movies' : 'Series', 'item': BASE_CANONICAL + (t.type === 'movie' ? '/movies/' : '/series/')}, {'@type': 'ListItem', 'position': 3, 'name': t.title, 'item': canon}]}];
  if (t.trailer) graph.push({'@type': 'VideoObject', 'name': t.title + ' — Official Trailer', 'embedUrl': 'https://www.youtube-nocookie.com/embed/' + t.trailer, 'contentUrl': 'https://www.youtube.com/watch?v=' + t.trailer, 'thumbnailUrl': BASE_CANONICAL + '/' + t.poster});
  ld.textContent = JSON.stringify({'@context': 'https://schema.org', '@graph': graph});
  document.head.appendChild(ld);
  /* per-view SEO for the detail view */
  const crumbEl = document.getElementById('dCrumb'); if (crumbEl) crumbEl.textContent = t.title;
  const mdEl = document.getElementById('metaDesc'); if (mdEl) mdEl.setAttribute('content', (t.title + ' (' + t.year + '): ' + t.genres.join(', ') + '. Rating, cast, seasons and where to watch legally in the USA & UK — on ReelOpal.').slice(0, 160));
  const _st = document.getElementById('ld-title'); if (_st) _st.remove();
  ['ld-faq','dynSeo'].forEach(function(id){ const _e = document.getElementById(id); if (_e) _e.remove(); });
  const _cl = document.getElementById('canonicalLink'); if (_cl) _cl.setAttribute('href', canon);
  const _ogu = document.querySelector('meta[property="og:url"]'); if (_ogu) _ogu.setAttribute('content', canon);
  const _ogt = document.querySelector('meta[property="og:title"]'); if (_ogt) _ogt.setAttribute('content', document.title);
  const _ogd = document.querySelector('meta[property="og:description"]'); if (_ogd) _ogd.setAttribute('content', document.getElementById('metaDesc').getAttribute('content'));
  const _ogi = document.querySelector('meta[property="og:image"]'); if (_ogi) _ogi.setAttribute('content', BASE_CANONICAL + '/' + t.poster);
  /* per-title legal-watch hint, from this title's own catalog data */
  const hint = document.getElementById('dWatchHint');
  if (hint) hint.innerHTML = t.type === 'movie'
    ? '<b>Where to watch ' + esc(t.title) + ' legally in ' + (t.region === 'EU' ? 'the UK' : 'the USA') + ':</b> via its official Apple TV ' + (t.region === 'EU' ? 'UK' : 'US') + ' store page (red button)' + (t.price ? ' — listed at ' + esc(t.price) + ' in the 16 Nov 2026 chart snapshot' : '') + '. Availability can differ in other countries; the store page shows your region\'s options. <a href="/where-to-watch/">How to check your country →</a>'
    : '<b>Where to watch ' + esc(t.title) + ' legally:</b> ' + (t.network ? 'listed network: <b>' + esc(t.network) + '</b>. ' : '') + 'The official TVMaze page (red button) lists official links. Availability differs between the USA, UK and EU — <a href="/where-to-watch/">see the Where to Watch guide</a>.';
  ReelOpalAnalytics.title(t.slug);
  window.scrollTo(0, 0);
}

/* All extras open directly. */
function exportWatchlist(){
  const list = TITLES.filter(t => watchlist.has(t.slug)).map(t => ({title: t.title, type: t.type, year: t.year, rating: t.rating, genres: t.genres, official_page: t.source, reelopal: '/titles/' + t.slug + '/'}));
  const blob = new Blob([JSON.stringify({exported_from: 'ReelOpal', date: '2026-11-16', watchlist: list}, null, 2)], {type: 'application/json'});
  const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = 'reelopal-watchlist.json'; a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 4000);
}
$('#exportBtn').addEventListener('click', () => {
  if (!watchlist.size) { toast('Your watchlist is empty — add a title first'); return; }
  exportWatchlist();
});
$('#clearWl').addEventListener('click', () => { watchlist.clear(); saveWl(); renderWatchlist(); toast('Watchlist cleared'); });

/* ================= TRAILER ================= */
function openTrailer(slug){
  const t = bySlug[slug]; if (!t || !t.trailer) return;
  $('#trailerTitle').textContent = t.title + ' — Official Trailer';
  $('#trailerFrame').src = 'https://www.youtube-nocookie.com/embed/' + t.trailer + '?rel=0';
  $('#trailerModal').classList.add('on');
}
function closeModals(){
  document.querySelectorAll('.modal').forEach(m => m.classList.remove('on'));
  const f = $('#trailerFrame'); if (f) f.src = '';
}

/* ================= SMARTLINK ================= */
let smartClicks = 0;
function syncSmartStatus(){
  const live = !!SMARTLINK_URL;
  document.querySelectorAll('[data-smart-status]').forEach(el => {
    el.classList.toggle('live', live); el.classList.toggle('demo', !live);
    const txt = el.querySelector('span'); if (txt) txt.textContent = live ? 'Smartlink is LIVE' : 'Demo mode — no SMARTLINK_URL set yet';
  });
  const c = document.getElementById('smartClicks'); if (c) c.textContent = smartClicks;
}
function openSmartlink(source){
  smartClicks++; syncSmartStatus(); ReelOpalAnalytics.smartlinkClick(source);
  if (SMARTLINK_URL) {
    window.open(SMARTLINK_URL, '_blank', 'noopener');
    toast('Opening today\'s sponsored pick…');
  } else {
    /* DEMO mode (no smartlink URL configured): preview instead of a dead link */
    $('#smartNote').textContent = 'Demo mode: no smartlink is configured yet. Paste your URL into SMARTLINK_URL at the top of the site code and every placement — including this one (' + (source || 'site') + ') — opens it in a new tab.';
    $('#smartModal').classList.add('on');
  }
}
const smartGo = document.getElementById('smartGoBtn');
if (smartGo) smartGo.addEventListener('click', () => {
  if (SMARTLINK_URL) { smartClicks++; syncSmartStatus(); ReelOpalAnalytics.smartlinkClick('smart-modal'); window.open(SMARTLINK_URL, '_blank', 'noopener'); closeModals(); }
  else toast('Demo mode — set SMARTLINK_URL in the site code to go live');
});
const smartBarClose = document.getElementById('smartBarClose');
if (smartBarClose) smartBarClose.addEventListener('click', () => { const b = document.getElementById('smartBar'); if (b) b.style.display = 'none'; });

/* ================= GLOBAL CLICKS ================= */
document.addEventListener('click', e => {
  const sl = e.target.closest('[data-smartlink]');
  if (sl) { e.preventDefault(); openSmartlink(sl.dataset.smartlink); return; }
  const wl = e.target.closest('[data-wl]');
  if (wl) {
    e.preventDefault(); e.stopPropagation();
    const slug = wl.dataset.wl;
    if (watchlist.has(slug)) { watchlist.delete(slug); toast('Removed from watchlist'); } else { watchlist.add(slug); toast('Added to watchlist'); }
    saveWl(); rerender();
    return;
  }
  const tr = e.target.closest('[data-trailer]');
  if (tr) { openTrailer(tr.dataset.trailer); return; }
  const hero = e.target.closest('[data-hero]');
  if (hero) { heroGo(+hero.dataset.hero); startHero(); return; }
  const again = e.target.closest('[data-mood-again]');
  if (again) { moodPick(again.dataset.moodAgain, document.querySelector('#moodRow button.on')); return; }
  const sc = e.target.closest('[data-scroll]');
  if (sc) { const el = document.getElementById(sc.dataset.scroll); if (el) el.scrollBy({left: +sc.dataset.dir * 560, behavior: 'smooth'}); return; }
  const card = e.target.closest('[data-open]');
  if (card) { nav('/titles/' + card.dataset.open + '/'); return; }
  const chip = e.target.closest('[data-genre]');
  if (chip && chip.closest('#genreChips')) { genreState = chip.dataset.genre; renderGenres(); return; }
  const qc = e.target.closest('[data-q]');
  if (qc) { $('#qInput').value = qc.dataset.q; renderSearch(qc.dataset.q); return; }
  const cp = e.target.closest('[data-copy]');
  if (cp) {
    const txt = document.getElementById(cp.dataset.copy).innerText;
    if (navigator.clipboard) navigator.clipboard.writeText(txt).then(() => toast('Copied to clipboard'));
    return;
  }
  const gl = e.target.closest('[data-genre-link]');
  if (gl) { genreState = gl.dataset.genreLink; return; }
  if (e.target.closest('[data-close]')) closeModals();
  if (e.target.classList.contains('modal')) closeModals();
});
document.addEventListener('keydown', e => {
  if (e.key === 'Escape') closeModals();
  if (e.key === 'Enter') { const card = e.target.closest && e.target.closest('[data-open]'); if (card) nav('/titles/' + card.dataset.open + '/'); }
});
document.querySelectorAll('#moodRow button').forEach(b => b.addEventListener('click', () => moodPick(b.dataset.mood, b)));
$('#dWl').addEventListener('click', () => {
  if (!currentDetail) return;
  const slug = currentDetail.slug;
  if (watchlist.has(slug)) watchlist.delete(slug); else watchlist.add(slug);
  saveWl(); renderDetail(slug); toast(watchlist.has(slug) ? 'Added to watchlist' : 'Removed from watchlist');
});
$('#hSearchForm').addEventListener('submit', e => { e.preventDefault(); nav('/search/?q=' + encodeURIComponent($('#hSearch').value)); });
$('#qInput').addEventListener('input', e => renderSearch(e.target.value));
['mvRegion','mvGenre','mvSort'].forEach(id => $('#' + id).addEventListener('change', renderMovies));
['srGenre','srRating','srSort'].forEach(id => $('#' + id).addEventListener('change', renderSeries));
['gnType','gnSort'].forEach(id => $('#' + id).addEventListener('change', renderGenres));

