const FAQ_LD = {"guides": {"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "What is the #1 trending series on Netflix right now?", "acceptedAnswer": {"@type": "Answer", "text": "Black Mirror leads the ReelOpal Netflix Top 10, a popularity ranking of Netflix series built from TVMaze data (snapshot: November 15, 2026). It is ReelOpal's ranking, not Netflix's official daily chart."}}, {"@type": "Question", "name": "Does ReelOpal host movies or episodes?", "acceptedAnswer": {"@type": "Answer", "text": "No. ReelOpal is a discovery guide. It publishes legal metadata, ratings, cast and trailers, and every title links out to its official provider page where you can watch it legally."}}, {"@type": "Question", "name": "Where does the data come from?", "acceptedAnswer": {"@type": "Answer", "text": "Series data, posters, cast and episode counts come from the TVMaze API. Movie charts and artwork come from Apple's official iTunes charts for the US and UK stores."}}, {"@type": "Question", "name": "Do I need an account to use ReelOpal?", "acceptedAnswer": {"@type": "Answer", "text": "No. Browsing, search, filters, the watchlist, the full episode breakdown, the HD poster pack and the watchlist export need no account — everything is open."}}, {"@type": "Question", "name": "Can I use ReelOpal in Europe?", "acceptedAnswer": {"@type": "Answer", "text": "Yes. ReelOpal tracks both the US and UK/European movie charts and marks each chart title with its region, so European viewers see what is trending near them."}}, {"@type": "Question", "name": "How is the Netflix Top 10 ranked?", "acceptedAnswer": {"@type": "Answer", "text": "The ranking orders Netflix-carried series by TVMaze's popularity weight, cross-checked against audience ratings, as of the November 15, 2026 catalog snapshot. Ties on weight are broken by audience rating, then alphabetically. It is a popularity ranking, not Netflix's official daily viewing chart."}}, {"@type": "Question", "name": "How do I choose what to watch tonight?", "acceptedAnswer": {"@type": "Answer", "text": "Use ReelOpal's mood picker on the home page, or start from the Netflix Top 10 snapshot and the US and UK movie charts. Every title page shows the rating, genres, cast and a link to the official provider, so you can decide in under a minute and watch legally."}}, {"@type": "Question", "name": "Is a title on Netflix USA?", "acceptedAnswer": {"@type": "Answer", "text": "ReelOpal's title pages show the network or provider recorded in the catalog data. Netflix catalogues differ by country, so open the title's official provider page and check while signed in to your own region — that page always shows the options for your country."}}, {"@type": "Question", "name": "Is ReelOpal legal?", "acceptedAnswer": {"@type": "Answer", "text": "Yes. ReelOpal is a discovery guide: it publishes metadata, ratings, cast and trailers from legal sources (the TVMaze API and Apple's official iTunes charts) and links out to official provider pages. It hosts no streams, no downloads and no pirated content."}}, {"@type": "Question", "name": "Where can I watch a title legally?", "acceptedAnswer": {"@type": "Answer", "text": "Open the title page and use the official provider button. Movies in the catalog link to their official Apple TV store page (US or UK store); series link to their official TVMaze page, which lists the network and official links. Availability differs between the USA, UK and EU."}}, {"@type": "Question", "name": "How does the watchlist work?", "acceptedAnswer": {"@type": "Answer", "text": "Tap the plus button on any poster, or 'Add to watchlist' on a title page. The list is stored in this browser only (localStorage), so it is private to this device and needs no account. You can export it as a file from the Watchlist page."}}, {"@type": "Question", "name": "What are the best movies on Netflix in November 2026?", "acceptedAnswer": {"@type": "Answer", "text": "ReelOpal answers this from its own catalog data: the Netflix Top 10 snapshot page ranks the most popular Netflix series (TVMaze-popularity snapshot, 16 Nov 2026), and the Best of 2026 page lists every 2026 title on the US and UK charts. Neither is Netflix's official chart."}}]}, "what-to-watch-tonight": {"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "What is the #1 show on Netflix tonight?", "acceptedAnswer": {"@type": "Answer", "text": "Black Mirror — #1 in the ReelOpal Netflix Top 10 for the week of 16–22 November 2026. It is a TVMaze-popularity snapshot dated 16 Nov 2026, not Netflix's official daily chart."}}, {"@type": "Question", "name": "What should I watch if I only have 30 minutes?", "acceptedAnswer": {"@type": "Answer", "text": "Pick a short episode: Arrested Development (8.2), BoJack Horseman (7.9) or Lovesick (7.3) — all three are in this week's Netflix Top 10 and stream on Netflix."}}, {"@type": "Question", "name": "Is this Netflix's official Top 10?", "acceptedAnswer": {"@type": "Answer", "text": "No. ReelOpal's ranking orders Netflix-carried series by TVMaze popularity weight, cross-checked with audience ratings. The snapshot is dated 16 November 2026."}}]}, "best-thriller-series-netflix-2026": {"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "What is the best thriller series on Netflix?", "acceptedAnswer": {"@type": "Answer", "text": "Black Mirror (8.4) — #1 in the ReelOpal thriller ranking and #1 in the Netflix Top 10 for the week of 16–22 November 2026 (TVMaze-popularity snapshot, 16 Nov 2026)."}}, {"@type": "Question", "name": "Is Black Mirror still running?", "acceptedAnswer": {"@type": "Answer", "text": "Yes. TVMaze lists Black Mirror as Running as of 16 November 2026. Each episode is a standalone story, so you can start with any season."}}, {"@type": "Question", "name": "Are all six thrillers on Netflix US?", "acceptedAnswer": {"@type": "Answer", "text": "The six series in the first list are Netflix-carried series in the TVMaze catalog. Netflix's catalogue rotates by country and month, so check netflix.com before you settle in — the title pages link to each show's official page."}}]}, "where-to-watch-top10-usa": {"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Is the whole Netflix Top 10 on Netflix US?", "acceptedAnswer": {"@type": "Answer", "text": "Yes. All 10 titles in the ReelOpal Netflix Top 10 for the week of 16–22 November 2026 are Netflix-carried series, led by Black Mirror at #1 — they stream on Netflix in the USA."}}, {"@type": "Question", "name": "Do I need to rent or buy the Top 10 titles?", "acceptedAnswer": {"@type": "Answer", "text": "No. A Netflix subscription covers all 10 series — no extra rental or purchase. Movies on the Apple TV charts are different: those link to Apple TV, where prices in the snapshot start at $4.99."}}, {"@type": "Question", "name": "How do I check a title is still available?", "acceptedAnswer": {"@type": "Answer", "text": "Open the title's page on ReelOpal for its official provider link, then confirm on netflix.com — Netflix's catalogue rotates, and availability differs outside the USA."}}]}, "best-2026": {"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Which titles on this page are actually from 2026?", "acceptedAnswer": {"@type": "Answer", "text": "All of them. Every title in the list above has 2026 as its release year in the catalog data — 59 movies in total, from the US Apple TV chart and the UK Apple TV chart in the 16 Nov 2026 snapshot."}}, {"@type": "Question", "name": "How was the Best of 2026 list chosen?", "acceptedAnswer": {"@type": "Answer", "text": "The list is not hand-picked opinions. It takes every title in the ReelOpal catalog whose recorded year is 2026 and orders it by its chart position — US chart first, then the UK chart — exactly as published in the 16 Nov 2026 snapshot."}}, {"@type": "Question", "name": "Where can I watch these 2026 movies legally?", "acceptedAnswer": {"@type": "Answer", "text": "Each movie links to its official Apple TV store page — the US store for US-chart titles and the UK store for UK-chart titles. Open the title page and use the official provider button."}}]}, "watch": {"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "Is ReelOpal legal?", "acceptedAnswer": {"@type": "Answer", "text": "Yes. ReelOpal is a discovery guide: it publishes metadata, ratings, cast and trailers from legal sources (the TVMaze API and Apple's official iTunes charts) and links out to official provider pages. It hosts no streams, no downloads and no pirated content."}}, {"@type": "Question", "name": "How do I check if a title is available in my country?", "acceptedAnswer": {"@type": "Answer", "text": "Open the title page, follow the official provider button, and check while signed in to your own region. Streaming catalogues differ between the USA, UK and EU, and the provider page always shows the options for your country."}}, {"@type": "Question", "name": "Why does availability differ between the USA and the UK?", "acceptedAnswer": {"@type": "Answer", "text": "Studios license titles country by country, so the same film or series can sit on different services — or none — in the US, UK and EU. That is why ReelOpal labels every chart title with its region and never promises one worldwide provider."}}, {"@type": "Question", "name": "Does ReelOpal host streams or downloads?", "acceptedAnswer": {"@type": "Answer", "text": "No. ReelOpal hosts no streams and no downloads. Every title links to its official provider page, where you can watch it legally."}}]}, "new": {"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "What does “new this week” mean on ReelOpal?", "acceptedAnswer": {"@type": "Answer", "text": "It means the newest titles in the current catalog snapshot — the 16 Nov 2026 build of the catalog — ordered by release year and chart position. ReelOpal dates the snapshot honestly instead of claiming a live feed."}}, {"@type": "Question", "name": "When was this list last updated?", "acceptedAnswer": {"@type": "Answer", "text": "The catalog snapshot is dated 16 Nov 2026 and this page was updated on 16 Nov 2026. The list changes when the catalog is rebuilt with newer chart and TVMaze data."}}, {"@type": "Question", "name": "Are these titles new on Netflix?", "acceptedAnswer": {"@type": "Answer", "text": "Not necessarily. The newest entries are 2026 movies from the official US and UK Apple TV charts. For Netflix specifically, see the Netflix Top 10 page — a TVMaze-popularity snapshot, not Netflix's official chart."}}]}, "usa": {"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "What are the best movies for US viewers right now?", "acceptedAnswer": {"@type": "Answer", "text": "On ReelOpal's data, the top of the official US Apple TV movie chart in the 16 Nov 2026 snapshot: Heart of the Beast at #1, followed by Resident Evil (2026) and Spider-Man: Brand New Day."}}, {"@type": "Question", "name": "What is the top Netflix series in the USA this week?", "acceptedAnswer": {"@type": "Answer", "text": "Black Mirror leads ReelOpal's Netflix Top 10 series this week USA ranking — a TVMaze-popularity snapshot dated 16 Nov 2026, not Netflix's official chart."}}, {"@type": "Question", "name": "Where can US viewers watch these titles legally?", "acceptedAnswer": {"@type": "Answer", "text": "Movies link to their official Apple TV US store page; series link to their official TVMaze page with the network and official links. See the Where to Watch guide for the full method."}}]}, "uk": {"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "What are the best movies on Netflix UK in November 2026?", "acceptedAnswer": {"@type": "Answer", "text": "ReelOpal answers from its own data: the UK Apple TV chart in the 16 Nov 2026 snapshot is led by Pressure, and the Netflix Top 10 snapshot page ranks the most popular Netflix series. Netflix's UK catalogue differs from the US one, and ReelOpal's Top 10 is a TVMaze-popularity snapshot — not Netflix's official UK chart."}}, {"@type": "Question", "name": "How is the UK chart different from the US chart?", "acceptedAnswer": {"@type": "Answer", "text": "The UK chart comes from Apple's UK iTunes store and the US chart from the US store, so titles, order and prices (GBP vs USD) differ. ReelOpal labels every movie with its region."}}, {"@type": "Question", "name": "Where can UK viewers watch these titles legally?", "acceptedAnswer": {"@type": "Answer", "text": "UK-chart movies link to their official Apple TV UK store page. For series, open the title page for the network and official links, and check availability signed in to your UK account."}}]}, "netflix": {"@context": "https://schema.org", "@type": "FAQPage", "mainEntity": [{"@type": "Question", "name": "What is the #1 trending series on Netflix right now?", "acceptedAnswer": {"@type": "Answer", "text": "Black Mirror leads the ReelOpal Netflix Top 10 — a popularity ranking of Netflix series built from TVMaze data (snapshot: Nov 16, 2026), not Netflix's official daily chart."}}, {"@type": "Question", "name": "Is this Netflix's official Top 10 chart?", "acceptedAnswer": {"@type": "Answer", "text": "No. Netflix's official chart is published inside the Netflix app and on Netflix's own Top 10 site, and it changes daily by country. ReelOpal's ranking is a TVMaze-popularity snapshot of Netflix-carried series, dated 16 Nov 2026, cross-checked against audience ratings."}}, {"@type": "Question", "name": "How is the Netflix Top 10 ranked?", "acceptedAnswer": {"@type": "Answer", "text": "The ranking orders Netflix-carried series by the popularity weight TVMaze assigns them, cross-checked against audience ratings, as of the November 14, 2026 catalog snapshot."}}, {"@type": "Question", "name": "What should I watch on Netflix tonight?", "acceptedAnswer": {"@type": "Answer", "text": "Start with the top three above — Black Mirror, Arrested Development and House of Cards — or use the mood picker on the home page. Each title page shows ratings, cast, seasons and the official provider link."}}]}};
function setDynSeo(m, url, items){
  let el = document.getElementById('dynSeo'); if (el) el.remove();
  el = document.createElement('script'); el.type = 'application/ld+json'; el.id = 'dynSeo';
  const graph = [{'@type':'BreadcrumbList','itemListElement':[{'@type':'ListItem','position':1,'name':'Home','item':BASE_CANONICAL},{'@type':'ListItem','position':2,'name':m.t.split('|')[0].trim(),'item':url}]}];
  if (items && items.length) graph.push({'@type':'ItemList','name':m.t.split('|')[0].trim(),'itemListOrder':'https://schema.org/ItemListOrderDescending','numberOfItems':items.length,'itemListElement':items.map((n,i)=>({'@type':'ListItem','position':i+1,'name':n}))});
  el.textContent = JSON.stringify({'@context':'https://schema.org','@graph':graph});
  document.head.appendChild(el);
}
function applySeo(key, items, ov){
  const base = VIEW_SEO[key]; if (!base && !ov) return;
  const m = ov || base;
  const url = BASE_CANONICAL + (m.p ? '/' + m.p + '/' : '/');
  document.title = m.t;
  const md = document.getElementById('metaDesc'); if (md) md.setAttribute('content', m.d);
  const cl = document.getElementById('canonicalLink'); if (cl) cl.setAttribute('href', url);
  const HL = {home:[BASE_CANONICAL+'/usa/', BASE_CANONICAL+'/uk/', BASE_CANONICAL+'/'], usa:[BASE_CANONICAL+'/usa/', BASE_CANONICAL+'/uk/', BASE_CANONICAL+'/'], uk:[BASE_CANONICAL+'/usa/', BASE_CANONICAL+'/uk/', BASE_CANONICAL+'/']};
  if (HL[key]) { ['hlUS','hlGB','hlXD'].forEach(function(id, i){ const el = document.getElementById(id); if (el) el.setAttribute('href', HL[key][i]); }); }
  const ogu = document.querySelector('meta[property="og:url"]'); if (ogu) ogu.setAttribute('content', url);
  const ogt = document.querySelector('meta[property="og:title"]'); if (ogt) ogt.setAttribute('content', m.t);
  const ogd = document.querySelector('meta[property="og:description"]'); if (ogd) ogd.setAttribute('content', m.d);
  const twt = document.querySelector('meta[name="twitter:title"]'); if (twt) twt.setAttribute('content', m.t);
  const twd = document.querySelector('meta[name="twitter:description"]'); if (twd) twd.setAttribute('content', m.d);
  /* drop stale per-page structured data, then re-create it for this view */
  ['ld-faq','ld-title','ld-items'].forEach(function(id){ const el = document.getElementById(id); if (el) el.remove(); });
  setDynSeo(m, url, items);
  if (FAQ_LD[key]) { const f = document.createElement('script'); f.type = 'application/ld+json'; f.id = 'ld-faq'; f.textContent = JSON.stringify(FAQ_LD[key]); document.head.appendChild(f); }
}
let currentGenre = 'thriller';
function renderBest2026(){
  const list = TITLES.filter(t => t.year === '2026').sort((a,b) => a.region === b.region ? (a.chart || 99) - (b.chart || 99) : (a.region === 'US' ? -1 : 1));
  fillGrid('b26Grid', list);
  const byG = {};
  list.forEach(t => t.genres.forEach(g => { (byG[g] = byG[g] || []).push(t); }));
  const gb = document.getElementById('b26GenreBody');
  if (gb) gb.innerHTML = Object.keys(byG).sort((a,b) => byG[b].length - byG[a].length).map(g => '<tr><td>' + esc(g) + '</td><td>' + byG[g].length + '</td><td>' + byG[g].slice(0,3).map(t => esc(t.title)).join(', ') + '</td></tr>').join('');
  applySeo('best-2026', list.map(t => t.title));
}
function renderNew(){
  const list = TITLES.filter(t => +t.year >= 2025).sort((a,b) => String(b.year).localeCompare(String(a.year)) || (a.chart || 99) - (b.chart || 99));
  fillGrid('newGrid', list);
  applySeo('new', list.map(t => t.title));
}
function renderWatch(){
  const counts = {};
  TITLES.forEach(t => { const p = t.type === 'movie' ? 'Apple TV (official store)' : (t.network || ''); if (p) counts[p] = (counts[p] || 0) + 1; });
  const what = {'Apple TV (official store)':'Official movie store pages — US store for US-chart titles, UK store for UK-chart titles', 'Netflix':'Streaming service — carries the Netflix Top 10 snapshot titles'};
  const rows = Object.keys(counts).sort((a,b) => counts[b] - counts[a]).slice(0, 12);
  const pb = document.getElementById('providerBody');
  if (pb) pb.innerHTML = rows.map(p => '<tr><td>' + esc(p) + '</td><td>' + counts[p] + '</td><td>' + esc(what[p] || 'Network recorded by TVMaze — the title page carries its official links') + '</td></tr>').join('');
}
function renderGeo(region){
  if (region === 'usa') { fillGrid('usaGrid', MOVIES.filter(m => m.region === 'US').sort((a,b) => a.chart - b.chart)); fillGrid('usaNfGrid', NF, true); applySeo('usa', NF.map(t => t.title)); }
  else { fillGrid('ukGrid', MOVIES.filter(m => m.region === 'EU').sort((a,b) => a.chart - b.chart)); fillGrid('ukNfGrid', NF, true); applySeo('uk', NF.map(t => t.title)); }
}
const GENRE_BEST = {
  'thriller': {name:'Thriller', match:t => t.genres.includes('Thriller')},
  'comedy': {name:'Comedy', match:t => t.genres.includes('Comedy')},
  'drama': {name:'Drama', match:t => t.genres.includes('Drama')},
  'action': {name:'Action', match:t => t.genres.some(g => g === 'Action' || g === 'Action & Adventure')},
  'sci-fi': {name:'Science-Fiction', label:'Sci-Fi', match:t => t.genres.includes('Science-Fiction')},
  'horror': {name:'Horror', match:t => t.genres.includes('Horror')}
};
function renderGenreBest(key){
  const cfg = GENRE_BEST[key] || GENRE_BEST.thriller;
  const label = cfg.label || cfg.name;
  const list = sortList(TITLES.filter(cfg.match), 'rating').slice(0, 12);
  const top = list[0]; if (!top) return;
  document.getElementById('gCrumb').textContent = 'Best ' + label;
  document.getElementById('gTitle').textContent = 'Best ' + label + ' Movies & Series';
  document.getElementById('gAnswer').innerHTML = '<strong>Direct answer:</strong> the highest-rated ' + esc(label.toLowerCase()) + ' title in ReelOpal\'s catalog is <strong>' + esc(top.title) + ' (' + esc(top.year) + ')' + (top.rating ? ', rated ★ ' + top.rating.toFixed(1) : '') + '</strong>. Below are the top ' + list.length + ' ' + esc(label.toLowerCase()) + ' titles by audience rating, each with its official watch link on its title page.' + (key === 'thriller' ? ' For the best thriller series on Netflix 2026 angle, note Black Mirror — a Netflix series — ranks in this list.' : '');
  fillGrid('gGrid', list);
  document.getElementById('gTableTitle').textContent = 'Top ' + Math.min(8, list.length) + ' ' + label + ' titles — facts';
  document.getElementById('gTableBody').innerHTML = list.slice(0, 8).map((t,i) => '<tr><td>' + (i+1) + '</td><td><a href="/titles/' + t.slug + '/">' + esc(t.title) + '</a></td><td>' + esc(t.year) + '</td><td>' + (t.rating ? '★ ' + t.rating.toFixed(1) : '—') + '</td><td>' + (t.type === 'movie' ? 'Movie' : 'Series') + '</td></tr>').join('');
  const faqs = [
    ['How was this ' + label + ' list ranked?', 'By audience rating in the catalog data (TVMaze for series; catalog snapshot 16 Nov 2026), highest first. Only titles whose recorded genres include ' + cfg.name + ' are listed.'],
    ['Where can I watch these ' + label.toLowerCase() + ' titles legally?', 'Open any title page and use the official provider button — movies link to their official Apple TV store page, series to their official TVMaze page with the network. See the Where to Watch guide for how to check your country.'],
    ['Are these ' + label.toLowerCase() + ' titles on Netflix?', 'Some are: series pages show the network recorded in the catalog (for example Netflix). Netflix catalogues differ between the USA and UK, so confirm on the official provider page for your region.']
  ];
  document.getElementById('gFaqTitle').textContent = 'Best ' + label + ' — Questions';
  document.getElementById('gFaq').innerHTML = faqs.map(f => '<details><summary>' + esc(f[0]) + '</summary><p>' + esc(f[1]) + '</p></details>').join('');
  const holder = document.getElementById('gLd'); holder.innerHTML = '';
  const ld = document.createElement('script'); ld.type = 'application/ld+json';
  ld.textContent = JSON.stringify({'@context':'https://schema.org','@type':'FAQPage','mainEntity':faqs.map(f => ({'@type':'Question','name':f[0],'acceptedAnswer':{'@type':'Answer','text':f[1]}}))});
  holder.appendChild(ld);
  const others = Object.keys(GENRE_BEST).filter(k => k !== key).map(k => '<a href="/genre/' + k + '/">Best ' + (GENRE_BEST[k].label || GENRE_BEST[k].name) + '</a>').join('');
  document.getElementById('gRel').innerHTML = '<a href="/">← Home</a><a href="/genres/">All Genres</a>' + others + '<a href="/netflix/">Netflix Top 10</a><a href="/where-to-watch/">Where to Watch Legally</a>';
  applySeo('genre-' + key, list.map(t => t.title));
}

