const VIEWS = ['home','movies','series','netflix','genres','search','detail','watchlist','guides','catalog','best-2026','genre','watch','new','usa','uk','dashboard','what-to-watch-tonight','best-thriller-series-netflix-2026','where-to-watch-top10-usa'];
/* Route aliases: the public hash slug on the left resolves to the registered view id on the right.
   'best-2026' is itself a registered view (view-best-2026), so #/best-2026 renders the Best of 2026 page directly. */
const ROUTE_MAP = {'best-2026':'best-2026','where-to-watch':'watch','new-this-week':'new'};
let currentView = 'home';
function rerender(){
  if (currentView === 'home') { renderHero(); fillTrack('nfTrack', NF, true); fillTrack('mvTrack', MOVIES.filter(m => m.region === 'US')); fillTrack('srTrack', sortList(SERIES, 'rating')); fillTrack('euTrack', MOVIES.filter(m => m.region === 'EU')); }
  else if (currentView === 'movies') renderMovies();
  else if (currentView === 'series') renderSeries();
  else if (currentView === 'genres') renderGenres();
  else if (currentView === 'watchlist') renderWatchlist();
  else if (currentView === 'catalog') renderCatalog();
  else if (currentView === 'detail' && currentDetail) renderDetail(currentDetail.slug);
  else if (currentView === 'best-2026') renderBest2026();
  else if (currentView === 'genre') renderGenreBest(currentGenre);
  else if (currentView === 'new') renderNew();
  else if (currentView === 'usa' || currentView === 'uk') renderGeo(currentView);
  else if (currentView === 'watch') renderWatch();
  else if (currentView === 'dashboard') renderDashboard();
  else if (currentView === 'what-to-watch-tonight') fillGrid('tonightGrid', ['black-mirror','marvel-s-daredevil','api-175-house-of-cards'].map(s => bySlug[s]).filter(Boolean), true);
  else if (currentView === 'best-thriller-series-netflix-2026') { fillGrid('nfThrGrid', ['black-mirror','longmire','api-175-house-of-cards','sense8','bloodline','api-33-hemlock-grove'].map(s => bySlug[s]).filter(Boolean)); fillGrid('moreThrGrid', ['api-169-breaking-bad','api-40-death-note','line-of-duty','api-61-orphan-black','api-64-utopia','api-7-homeland','api-16-penny-dreadful','api-35-the-killing','api-167-24'].map(s => bySlug[s]).filter(Boolean)); }
  else if (currentView === 'where-to-watch-top10-usa') fillGrid('w2wGrid', NF, true);
}
/* ================= REAL-PATHS ROUTER (History API) =================
   Old links used #/movies, #/title/<slug> ... — on load, a hash like that is
   redirected once to the equivalent real path (location.replace, so the
   hash URL never stays in history). In-page navigation uses pushState. */
const HASH_DESTS = {'':'/','movies':'/movies/','series':'/series/','netflix':'/netflix/','best-2026':'/best-2026/','new-this-week':'/new-this-week/','where-to-watch':'/where-to-watch/','usa':'/usa/','uk':'/uk/','guides':'/guides/','catalog':'/catalog/','genres':'/genres/','search':'/search/','watchlist':'/watchlist/','dashboard':'/dashboard/','what-to-watch-tonight':'/what-to-watch-tonight/','best-thriller-series-netflix-2026':'/best-thriller-series-netflix-2026/','where-to-watch-top10-usa':'/where-to-watch-top10-usa/'};
(function redirectOldHash(){
  const h = location.hash || '';
  if (h.indexOf('#/') !== 0) return;
  const raw = h.replace(/^#\/?/, '');
  const qpos = raw.indexOf('?');
  const path = qpos === -1 ? raw : raw.slice(0, qpos);
  const qs = qpos === -1 ? '' : raw.slice(qpos);
  const segs = path.split('/').filter(Boolean);
  let dest = '/';
  if (segs[0] === 'title' && segs[1]) dest = '/titles/' + segs[1] + '/';
  else if (segs[0] === 'genre' && segs[1] && GENRE_BEST[segs[1]]) dest = '/genre/' + segs[1] + '/';
  else if (segs[0] === 'where-to-watch') dest = '/where-to-watch/' + (segs[1] ? segs[1] + '/' : '');
  else if (segs[0] === 'search') dest = '/search/' + qs;
  else if (segs[0] && HASH_DESTS[segs[0]]) dest = HASH_DESTS[segs[0]];
  location.replace(dest);
})();
function nav(path){ history.pushState({}, '', path); route(); }
function route(){
  const raw = location.pathname.replace(/^\/+|\/+$/g, '');
  const parts = raw ? raw.split('/') : [];
  const params = new URLSearchParams(location.search || '');
  let view = 'home'; let region = '';
  if (parts[0] === 'titles' && parts[1]) { view = 'detail'; }
  else if (parts[0] === 'genre' && parts[1] && GENRE_BEST[parts[1]]) { view = 'genre'; currentGenre = parts[1]; }
  else if (parts[0] === 'where-to-watch') { view = 'watch'; if (parts[1]) region = parts[1]; }
  else if (parts[0] === 'new-this-week') { view = 'new'; }
  else if (parts[0] === 'best-2026') { view = 'best-2026'; }
  else if (VIEWS.includes(parts[0])) view = parts[0];
  currentView = view;
  VIEWS.forEach(v => { const el = document.getElementById('view-' + v); if (el) el.classList.toggle('on', v === view); });
  document.querySelectorAll('#mainNav a').forEach(a => a.classList.toggle('on', a.dataset.nav === view || (view === 'detail' && a.dataset.nav === 'home') || (view === 'genre' && a.dataset.nav === 'genres')));
  if (view === 'detail') renderDetail(decodeURIComponent(parts[1]));
  else if (view === 'home') { rerender(); startHero(); window.scrollTo(0, 0); applySeo('home'); }
  else if (view === 'search') { const q = params.get('q') || ''; const qi = $('#qInput'); if (qi) qi.value = q; renderSearch(q); window.scrollTo(0, 0); applySeo('search'); }
  else if (view === 'netflix') { fillGrid('nfGrid', NF, true); window.scrollTo(0, 0); applySeo('netflix', NF.map(t => t.title)); }
  else if (view === 'catalog') { renderCatalog(); window.scrollTo(0, 0); applySeo('catalog'); }
  else if (view === 'best-2026') { renderBest2026(); window.scrollTo(0, 0); }
  else if (view === 'genre') { renderGenreBest(currentGenre); window.scrollTo(0, 0); }
  else if (view === 'watch') { renderWatch(); window.scrollTo(0, 0); applySeo('watch'); if (region) { const el = document.getElementById('watch-' + region); if (el) setTimeout(() => el.scrollIntoView(), 80); } }
  else if (view === 'new') { renderNew(); window.scrollTo(0, 0); }
  else if (view === 'usa') { renderGeo('usa'); window.scrollTo(0, 0); }
  else if (view === 'uk') { renderGeo('uk'); window.scrollTo(0, 0); }
  else if (view === 'dashboard') { renderDashboard(); window.scrollTo(0, 0); applySeo('dashboard'); }
  else if (view === 'what-to-watch-tonight') { fillGrid('tonightGrid', ['api-305-black-mirror','api-321-arrested-development','api-175-house-of-cards'].map(s => bySlug[s]).filter(Boolean), true); window.scrollTo(0, 0); applySeo('what-to-watch-tonight'); }
  else if (view === 'best-thriller-series-netflix-2026') { fillGrid('nfThrGrid', ['api-305-black-mirror','api-395-longmire','api-175-house-of-cards'].map(s => bySlug[s]).filter(Boolean)); fillGrid('moreThrGrid', ['api-169-breaking-bad','api-5-true-detective','api-81-criminal-minds','api-69-the-blacklist','api-30-american-horror-story','api-1-under-the-dome','verity','primetime','the-end-of-oak-street'].map(s => bySlug[s]).filter(Boolean)); window.scrollTo(0, 0); applySeo('best-thriller-series-netflix-2026'); }
  else if (view === 'where-to-watch-top10-usa') { fillGrid('w2wGrid', NF, true); window.scrollTo(0, 0); applySeo('where-to-watch-top10-usa', NF.map(t => t.title)); }
  else { rerender(); window.scrollTo(0, 0); applySeo(view); }
  if (view !== 'home') { clearInterval(heroTimer); }
  ReelOpalAnalytics.pageview(view);
}
window.addEventListener('popstate', route);
/* SPA link interception: same-origin /... links navigate without a reload. */
document.addEventListener('click', function(e){
  const a = e.target.closest && e.target.closest('a[href^="/"]');
  if (!a || a.hasAttribute('data-smartlink') || a.target === '_blank') return;
  const href = a.getAttribute('href');
  if (!href || href.indexOf('//') === 0) return;
  e.preventDefault();
  nav(href);
});


/* ================= LIVE API CATALOG (TVMaze, no key) — 176+ ================= */
let apiLoaded=false, catShownCount=48;
function slugify(s){return String(s||'title').toLowerCase().replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'').slice(0,60)}
function stripHtml(s){return String(s||'').replace(/<[^>]+>/g,' ').replace(/\s+/g,' ').trim()}
async function loadLiveCatalog(){
  /* STATIC BUILD — FROZEN SNAPSHOT (16 Nov 2026). The live TVMaze refresh is
     DISABLED on purpose: the catalog stays at the baked 176 titles, counts
     never diverge, and no live-added title can 404. Re-enable the fetch
     only if the catalog is re-baked at the same time. */
  const statusEl=document.getElementById('apiStatusText'); const catStatus=document.getElementById('catStatus');
  fillTrack('liveTrack', TITLES.filter(x=>x.baked).sort((a,b)=>(b.rating||0)-(a.rating||0)).slice(0,24));
  (function(){ const st=document.getElementById('statTotal'); if(st) st.textContent=TITLES.length+'+'; const ss=document.getElementById('statSeries'); if(ss) ss.textContent=TITLES.filter(x=>x.type==='series').length+'+'; const gt=document.getElementById('gTiles'); if(gt && !gt.innerHTML){ const topG=[...new Set(TITLES.flatMap(x=>x.genres))].slice(0,12); gt.innerHTML=topG.map(g=>'<button class="gtile" data-gtile="'+esc(g)+'" style="background:'+genreColor(g)+';color:#111"><span>'+esc(g)+'</span><small>'+TITLES.filter(x=>x.genres.includes(g)).length+' titles \u2192</small></button>').join(''); } })();
  const msg='Frozen snapshot — live TVMaze refresh is disabled in this static build. Showing the baked catalog: '+TITLES.length+' real titles (snapshot 16 Nov 2026) with posters, ratings & official pages.';
  if(statusEl) statusEl.textContent=msg;
  if(catStatus) catStatus.textContent=msg;
}
function renderCatalog(){
  const q=(document.getElementById('catQ').value||'').toLowerCase(); const type=document.getElementById('catType').value; const genre=document.getElementById('catGenre').value; const sort=document.getElementById('catSort').value;
  genreOptions('catGenre', TITLES);
  let list=TITLES.filter(t=>(!type||t.type===type)&&(!genre||t.genres.includes(genre))&&(!q||t.title.toLowerCase().includes(q)||t.genres.some(g=>g.toLowerCase().includes(q))||(t.network||'').toLowerCase().includes(q)));
  list=sortList(list, sort==='rating'?'rating':sort);
  document.getElementById('catCount').textContent=list.length+' titles';
  fillGrid('catGrid', list.slice(0,catShownCount));
  document.getElementById('catShown').textContent='Showing '+Math.min(catShownCount,list.length)+' of '+list.length+' — scroll down / load more for the rest';
  document.getElementById('catMore').style.display=list.length>catShownCount?'inline-flex':'none';
}
/* scroll design: progress, toTop, reveal, drag-scroll */
window.addEventListener('scroll',()=>{ const h=document.documentElement; const pct=h.scrollTop/(h.scrollHeight-h.clientHeight)*100; const bar=document.getElementById('scrollProgress'); if(bar) bar.style.width=pct+'%'; const tt=document.getElementById('toTop'); if(tt) tt.classList.toggle('on',h.scrollTop>600); },{passive:true});
document.addEventListener('click',e=>{ if(e.target&&e.target.id==='toTop') window.scrollTo({top:0,behavior:'smooth'}); const gt=e.target.closest&&e.target.closest('[data-gtile]'); if(gt){ genreState=gt.dataset.gtile; nav('/genres/'); } });
const io=('IntersectionObserver' in window)?new IntersectionObserver(es=>es.forEach(en=>{if(en.isIntersecting)en.target.classList.add('in')}),{threshold:.08}):null;
function armReveals(){ document.querySelectorAll('.reveal:not(.in)').forEach(el=>{ if(io) io.observe(el); else el.classList.add('in'); }); }
document.querySelectorAll('.track').forEach(tr=>{ let down=false,startX=0,startL=0; tr.addEventListener('pointerdown',e=>{down=true;startX=e.clientX;startL=tr.scrollLeft;tr.classList.add('dragging')}); window.addEventListener('pointermove',e=>{if(down) tr.scrollLeft=startL-(e.clientX-startX)}); window.addEventListener('pointerup',()=>{down=false;tr.classList.remove('dragging')}); });
['catQ'].forEach(id=>{const el=document.getElementById(id); if(el) el.addEventListener('input',()=>{catShownCount=48;renderCatalog()})});
['catType','catGenre','catSort'].forEach(id=>{const el=document.getElementById(id); if(el) el.addEventListener('change',()=>{catShownCount=48;renderCatalog()})});
const cm=document.getElementById('catMore'); if(cm) cm.addEventListener('click',()=>{catShownCount+=48;renderCatalog()});


/* ================= SITE-WIDE ANALYTICS LOADERS (GA4 / Plausible placeholders) =================
   Both IDs are empty by default: nothing loads and nothing is sent anywhere.
   Paste GA_MEASUREMENT_ID or PLAUSIBLE_DOMAIN at the top of this script and
   the matching script loads here; the Dashboard status then reads Connected. */
(function initExternalAnalytics(){
  try {
    if (GA_MEASUREMENT_ID) {
      const sc = document.createElement('script'); sc.async = true;
      sc.src = 'https://www.googletagmanager.com/gtag/js?id=' + encodeURIComponent(GA_MEASUREMENT_ID);
      document.head.appendChild(sc);
      window.dataLayer = window.dataLayer || [];
      window.gtag = function(){ window.dataLayer.push(arguments); };
      window.gtag('js', new Date()); window.gtag('config', GA_MEASUREMENT_ID);
    }
    if (PLAUSIBLE_DOMAIN) {
      const ps = document.createElement('script'); ps.defer = true;
      ps.setAttribute('data-domain', PLAUSIBLE_DOMAIN);
      ps.src = 'https://plausible.io/js/script.js';
      document.head.appendChild(ps);
    }
  } catch(e){}
})();

/* ================= DASHBOARD (#/dashboard) =================
   Renders ONLY window.ReelOpalAnalytics data (localStorage, this browser)
   plus the existing in-memory session counter `smartClicks` for smartlink.
   No backend, no cookies, no invented numbers. */
const DASH_PAGE_LABELS = {home:'Home', movies:'Movies', series:'Series', netflix:'Netflix Top 10', 'best-2026':'Best of 2026', new:'New This Week', watch:'Where to Watch', usa:'Best for US Viewers', uk:'Best for UK Viewers', catalog:'All 176+ Catalog', genres:'Genres', genre:'Best by Genre', search:'Search', watchlist:'Watchlist', guides:'Guides & FAQ', detail:'Title Detail', dashboard:'Dashboard'};
function dashTopList(obj, n){ return Object.keys(obj || {}).map(k => [k, obj[k]]).sort((a,b) => b[1] - a[1]).slice(0, n || 10); }
function dashTitleName(slug){ const tt = bySlug[slug]; return tt ? tt.title : slug; }
function estimateRegion(){
  let tz = ''; try { tz = Intl.DateTimeFormat().resolvedOptions().timeZone || ''; } catch(e){}
  const lang = navigator.language || '';
  let region = 'Unknown';
  const m = lang.match(/-([A-Za-z]{2})\b/); const cc = m ? m[1].toUpperCase() : '';
  const names = {US:'United States', GB:'United Kingdom', CA:'Canada', AU:'Australia', NZ:'New Zealand', DE:'Germany', FR:'France', ES:'Spain', IT:'Italy', NL:'Netherlands', BE:'Belgium', PT:'Portugal', MA:'Morocco', DZ:'Algeria', TN:'Tunisia', EG:'Egypt', IN:'India', BR:'Brazil', MX:'Mexico', JP:'Japan', KR:'South Korea', CN:'China', AE:'United Arab Emirates', SA:'Saudi Arabia'};
  if (cc && names[cc]) region = names[cc];
  else if (tz.indexOf('Europe/') === 0) region = 'Europe';
  else if (tz.indexOf('America/') === 0) region = 'North America';
  else if (tz.indexOf('Africa/') === 0) region = 'Africa';
  else if (tz.indexOf('Asia/') === 0) region = 'Asia';
  else if (tz.indexOf('Australia/') === 0 || tz.indexOf('Pacific/') === 0) region = 'Oceania';
  return {tz: tz, lang: lang, region: region};
}
function dashTotals(){
  const s = ReelOpalAnalytics.summary();
  const todayKey = ReelOpalAnalytics.today();
  const day = (s.days && s.days[todayKey]) || {views:0, unique:false, titles:{}, pages:{}, referrers:{}, smartlink:0, details:0, utm:{}};
  let totalViews = Object.keys(s.days || {}).reduce((a,k) => a + ((s.days[k] || {}).views || 0), 0);
  if (!totalViews) totalViews = Object.keys(s.pages || {}).reduce((a,k) => a + (s.pages[k] || 0), 0);
  const uniqueDays = Object.keys(s.days || {}).filter(k => (s.days[k] || {}).unique).length;
  const topTitleToday = dashTopList(day.titles, 1)[0] || null;
  const topRefToday = dashTopList(day.referrers, 1)[0] || null;
  const topTitleAll = dashTopList(s.titles, 1)[0] || null;
  return {s:s, todayKey:todayKey, day:day, totalViews:totalViews, uniqueDays:uniqueDays, topTitleToday:topTitleToday, topRefToday:topRefToday, topTitleAll:topTitleAll};
}
function renderDashboard(){
  const T = dashTotals(); const s = T.s; const day = T.day;
  const dateEl = document.getElementById('dashDate'); if (dateEl) dateEl.textContent = T.todayKey;
  const emptyEl = document.getElementById('dashEmpty'); if (emptyEl) emptyEl.hidden = T.totalViews > 0;
  const sumEl = document.getElementById('dashSummary');
  if (sumEl) sumEl.innerHTML =
    '<div class="dash-card"><b>' + (day.unique ? 1 : 0) + '</b><span>Visitors today</span><small>Unique-visitor flag for today — this browser only, per-device estimate.</small></div>' +
    '<div class="dash-card"><b>' + (day.views || 0) + '</b><span>Page views today</span><small>Views recorded today on this browser.</small></div>' +
    '<div class="dash-card"><b>' + (T.topTitleToday ? esc(dashTitleName(T.topTitleToday[0])) : '—') + '</b><span>Top title today</span><small>' + (T.topTitleToday ? T.topTitleToday[1] + ' view(s) today on this browser.' : 'No title views recorded yet today on this browser.') + '</small></div>' +
    '<div class="dash-card"><b>' + (T.topRefToday ? esc(T.topRefToday[0]) : '—') + '</b><span>Top referrer today</span><small>' + (T.topRefToday ? T.topRefToday[1] + ' visit(s) today via this referrer type.' : 'No visits recorded yet today on this browser.') + '</small></div>';
  const stEl = document.getElementById('dashStats');
  if (stEl) stEl.innerHTML =
    '<div class="dash-card"><b>' + T.totalViews + '</b><span>Total page views — all time</span><small>All views recorded on this browser.</small></div>' +
    '<div class="dash-card"><b>' + (day.views || 0) + '</b><span>Page views — today</span><small>' + esc(T.todayKey) + '</small></div>' +
    '<div class="dash-card"><b>' + T.uniqueDays + '</b><span>Unique-visitor days</span><small>Days this browser counted once as a unique visitor (max 1 per day) — this browser only, per-device estimate, not site-wide traffic.</small></div>' +
    '<div class="dash-card"><b>' + (s.smartlink || 0) + '</b><span>Smartlink clicks — all time</span><small>Today: ' + (day.smartlink || 0) + ' · This session: ' + smartClicks + ' (live session counter).</small></div>' +
    '<div class="dash-card"><b>' + Object.keys(s.days || {}).length + '</b><span>Days with recorded visits</span><small>Days present in this browser\u2019s local record.</small></div>';
  const ttEl = document.getElementById('dashTopTitles');
  if (ttEl) { const rows = dashTopList(s.titles, 10); ttEl.innerHTML = rows.length ? '<table class="tbl"><thead><tr><th>#</th><th>Title</th><th>Views</th></tr></thead><tbody>' + rows.map((r,i) => '<tr><td>' + (i+1) + '</td><td><a href="/titles/' + esc(r[0]) + '/">' + esc(dashTitleName(r[0])) + '</a></td><td>' + r[1] + '</td></tr>').join('') + '</tbody></table>' : '<p>No title views recorded yet on this browser.</p>'; }
  const tpEl = document.getElementById('dashTopPages');
  if (tpEl) { const rows = dashTopList(s.pages, 10); tpEl.innerHTML = rows.length ? '<table class="tbl"><thead><tr><th>#</th><th>Page</th><th>Views</th></tr></thead><tbody>' + rows.map((r,i) => '<tr><td>' + (i+1) + '</td><td>' + esc(DASH_PAGE_LABELS[r[0]] || r[0]) + '</td><td>' + r[1] + '</td></tr>').join('') + '</tbody></table>' : '<p>No page views recorded yet on this browser.</p>'; }
  const rfEl = document.getElementById('dashRefs');
  if (rfEl) { const refs = s.referrers || {}; const tot = ['search','social','direct','other'].reduce((a,k) => a + (refs[k] || 0), 0); rfEl.innerHTML = '<p style="margin-top:0">From document.referrer + UTM parameters (utm_source / utm_medium / utm_campaign), classified per visit on this browser.</p>' + ['search','social','direct','other'].map(k => { const v = refs[k] || 0; const pct = tot ? Math.round(v / tot * 100) : 0; return '<div class="bar-row"><span>' + k + '</span><div class="bar-track"><div class="bar-fill" style="width:' + pct + '%"></div></div><span class="n">' + v + '</span></div>'; }).join(''); }
  const utmEl = document.getElementById('dashUtm');
  if (utmEl) { const rows = dashTopList(s.utm, 8); utmEl.innerHTML = rows.length ? '<p style="margin:12px 0 4px"><strong style="color:#fff">UTM tags seen:</strong></p>' + rows.map(r => '<p style="margin:2px 0">' + esc(r[0]) + ' — ' + r[1] + ' visit(s)</p>').join('') : '<p style="margin:12px 0 0">No UTM parameters recorded yet on this browser.</p>'; }
  const geoEl = document.getElementById('dashGeo');
  if (geoEl) { const g = estimateRegion(); geoEl.innerHTML = '<p style="margin-top:0"><strong style="color:var(--gold)">ESTIMATE — never a fact:</strong> this browser looks like it is in <strong style="color:#fff">' + esc(g.region) + '</strong>.</p><p>Browser language: <strong style="color:#fff">' + esc(g.lang || 'unknown') + '</strong><br/>Browser time zone: <strong style="color:#fff">' + esc(g.tz || 'unknown') + '</strong></p><p>This is inferred only from this browser\u2019s own language and time-zone settings. It is an estimate about this device only — it is not measured, and it says nothing about where other visitors are.</p>'; }
  const dyEl = document.getElementById('dashDays');
  if (dyEl) { const keys = Object.keys(s.days || {}).sort().reverse().slice(0, 14); dyEl.innerHTML = keys.length ? '<table class="tbl"><thead><tr><th>Date</th><th>Page views</th><th>Unique visitor</th><th>Smartlink clicks</th></tr></thead><tbody>' + keys.map(k => { const d = s.days[k] || {}; return '<tr><td>' + esc(k) + '</td><td>' + (d.views || 0) + '</td><td>' + (d.unique ? 'Yes (1)' : 'No (0)') + '</td><td>' + (d.smartlink || 0) + '</td></tr>'; }).join('') + '</tbody></table><p>Unique visitors are counted once per day per browser (localStorage flag) — this browser only, a per-device estimate, not site-wide traffic.</p>' : '<p>No visits recorded yet on this browser.</p>'; }
  const exEl = document.getElementById('dashExt');
  if (exEl) { const gaOn = !!GA_MEASUREMENT_ID; const plOn = !!PLAUSIBLE_DOMAIN; exEl.innerHTML =
    '<p style="margin-top:0"><span class="smart-status ' + (gaOn ? 'live' : 'demo') + '"><i></i><span>GA4: ' + (gaOn ? 'Connected' : 'Not connected') + '</span></span> <span class="smart-status ' + (plOn ? 'live' : 'demo') + '"><i></i><span>Plausible: ' + (plOn ? 'Connected' : 'Not connected') + '</span></span></p>' +
    '<p>Real site-wide traffic (all visitors, not just this browser) only appears once GA4 or Plausible is connected. Until then, this dashboard shows this browser\u2019s own visits only. Setup steps for both are in <a href="/guides/" style="color:var(--gold);font-weight:800">Guides &amp; FAQ</a>: create a GA4 property and paste its measurement ID into GA_MEASUREMENT_ID, or set up Plausible and paste the domain into PLAUSIBLE_DOMAIN — both sit at the top of the site code and are empty by default.</p>'; }
}
function buildDailyReport(){
  const T = dashTotals(); const s = T.s; const day = T.day; const g = estimateRegion();
  const refs = s.referrers || {}; const refsToday = day.referrers || {};
  const utmRows = dashTopList(s.utm, 8);
  const lines = [
    'ReelOpal — Daily Visitor Report',
    'Date: ' + T.todayKey,
    'Scope: this browser only (localStorage) — per-device estimate, not site-wide traffic.',
    '',
    'TODAY',
    'Visitors today (unique, this browser): ' + (day.unique ? 1 : 0),
    'Page views today: ' + (day.views || 0),
    'Top title today: ' + (T.topTitleToday ? dashTitleName(T.topTitleToday[0]) + ' (' + T.topTitleToday[1] + ' views)' : 'none recorded'),
    'Top referrer today: ' + (T.topRefToday ? T.topRefToday[0] + ' (' + T.topRefToday[1] + ' visits)' : 'none recorded'),
    'Referrers today: search ' + (refsToday.search || 0) + ' · social ' + (refsToday.social || 0) + ' · direct ' + (refsToday.direct || 0) + ' · other ' + (refsToday.other || 0),
    'Smartlink clicks today: ' + (day.smartlink || 0),
    '',
    'ALL TIME (this browser)',
    'Total page views: ' + T.totalViews,
    'Unique-visitor days: ' + T.uniqueDays,
    'Top title all time: ' + (T.topTitleAll ? dashTitleName(T.topTitleAll[0]) + ' (' + T.topTitleAll[1] + ' views)' : 'none recorded'),
    'Referrers all time: search ' + (refs.search || 0) + ' · social ' + (refs.social || 0) + ' · direct ' + (refs.direct || 0) + ' · other ' + (refs.other || 0),
    'UTM tags: ' + (utmRows.length ? utmRows.map(r => r[0] + ' (' + r[1] + ')').join('; ') : 'none recorded'),
    'Smartlink clicks all time: ' + (s.smartlink || 0) + ' (this session: ' + smartClicks + ')',
    '',
    'Estimated region (this browser, ESTIMATE only): ' + g.region + ' — language ' + (g.lang || 'unknown') + ', time zone ' + (g.tz || 'unknown'),
    'GA4: ' + (GA_MEASUREMENT_ID ? 'Connected' : 'Not connected') + ' · Plausible: ' + (PLAUSIBLE_DOMAIN ? 'Connected' : 'Not connected'),
    'Note: real site-wide traffic appears only once GA4 or Plausible is connected; until then this report covers this browser only.'
  ];
  return lines.join('\n');
}
const dashExportBtn = document.getElementById('dashExport');
if (dashExportBtn) dashExportBtn.addEventListener('click', () => {
  const txt = buildDailyReport();
  const blob = new Blob([txt], {type: 'text/plain'});
  const a = document.createElement('a'); a.href = URL.createObjectURL(blob); a.download = 'reelopal-daily-report-' + ReelOpalAnalytics.today() + '.txt'; a.click();
  setTimeout(() => URL.revokeObjectURL(a.href), 4000);
  if (navigator.clipboard && navigator.clipboard.writeText) navigator.clipboard.writeText(txt).then(() => toast('Daily report downloaded & copied to clipboard'), () => toast('Daily report downloaded'));
  else toast('Daily report downloaded');
});
